// Minimal C impl
#include <stdlib.h>
#include <math.h>
#include <string.h>
char* process_stream(const double* data, size_t len, cb_t cb, void* ctx){
  double sum=0, max=-INFINITY;
  for(size_t i=0;i<len;++i){ double v=data[i]; sum+=v; if(v>max) max=v; cb(v, ctx);} 
  double mean = (len? sum/len:0);
  char* json = malloc(128);
  if(!json) return NULL;
  snprintf(json,128,"{\"total\":%zu,\"mean\":%f,\"max\":%f}", len, mean, max);
  return json;
}
